                        "code": "import numpy as np\n\n# Implementasi Penuh Low-Rank Adaptation (LoRA) Forward Pass & Weight Folding (Hu et al., 2022)\nclass LoRALinear:\n    def __init__(self, in_features, out_features, r=4, alpha=8.0):\n        self.in_features = in_features\n        self.out_features = out_features\n        self.r = r\n        self.scaling = alpha / r\n        \n        # Frozen Base Weight W0\n        np.random.seed(42)\n        self.W0 = np.random.randn(out_features, in_features) * 0.05\n        \n        # Trainable low-rank matrices A and B\n        self.A = np.random.randn(r, in_features) * 0.01  # Gaussian init\n        self.B = np.zeros((out_features, r))             # Zero init (Hu et al. 2022)\n        \n    def forward(self, x):\n        # h = W0 * x + (alpha/r) * B * A * x\n        base_out = np.dot(x, self.W0.T)\n        lora_out = np.dot(np.dot(x, self.A.T), self.B.T) * self.scaling\n        return base_out + lora_out\n        \n    def merge_weights(self):\n        # Lipat bobot LoRA ke bobot dasar untuk zero latency deployment\n        return self.W0 + self.scaling * np.dot(self.B, self.A)\n\nd_in, d_out = 8, 8\nlora_layer = LoRALinear(d_in, d_out, r=2, alpha=4.0)\nx = np.random.randn(1, d_in)\n\nout_initial = lora_layer.forward(x)\n# Mock pembaruan matriks B setelah beberapa langkah latihan\nlora_layer.B += np.random.randn(d_out, 2) * 0.02\nout_trained = lora_layer.forward(x)\n\nW_merged = lora_layer.merge_weights()\nout_merged = np.dot(x, W_merged.T)\n\nprint(f\"Total Parameter Base W0 : {d_in * d_out} (Frozen)\")\nprint(f\"Total Parameter LoRA (A+B): {lora_layer.r * (d_in + d_out)} (Trainable, Penghematan: {100*(1 - 32/64):.1f}%)\")\nprint(f\"Perbedaan Output (LoRA Forward vs Merged Weight): {np.max(np.abs(out_trained - out_merged)):.10e}\")",
